    private static function bytes(string $value): int {$value=trim($value);if($value==='-1'||$value==='0')return PHP_INT_MAX;$n=(float)$value;$unit=strtolower(substr($value,-1));return (int)($n*($unit==='g'?1073741824:($unit==='m'?1048576:($unit==='k'?1024:1))));}
    public static function inspect(?int $now=null): array {
        $now=$now??time();$c=OperationsSettings::get();$checks=array();$stats=array();$state=Operations::state();$add=static function($key,$status,$message)use(&$checks){$checks[$key]=array('state'=>$status,'message'=>$message);};
        try{$s=new Store();$enabled=$s->enabled();$add('configuration','OK',$enabled?eipsi_admin_translate('API enabled.'):eipsi_admin_translate('API disabled; internal maintenance remains available.'));
            $s->row('SELECT 1 reachable');$add('database','OK',eipsi_admin_translate('Local connection available; no destructive benchmark.'));
            $stats=$s->row($s->prepare("SELECT COUNT(*) exports,COALESCE(SUM(state IN ('READY','PREPARING') AND expires_at>%d),0) active_exports,COALESCE(SUM(state='PREPARING' AND expires_at>%d),0) preparing,COALESCE(SUM(state='READY'),0) ready_exports,COALESCE(SUM(state='FAILED'),0) failed_exports,COALESCE(SUM(storage_bytes),0) logical_bytes,COALESCE(SUM(CASE WHEN state='PREPARING' THEN storage_bytes ELSE 0 END),0) preparing_bytes,COALESCE(SUM(CASE WHEN state='READY' THEN storage_bytes ELSE 0 END),0) ready_bytes,COALESCE(SUM(CASE WHEN state IN ('FAILED','REVOKED','EXPIRED') OR expires_at<=%d THEN storage_bytes ELSE 0 END),0) terminal_bytes,COALESCE(SUM(state='PREPARING' AND last_progress_at<%d AND created_at<%d),0) stale_preparing,COALESCE(SUM(state='PREPARING' AND lease_token IS NOT NULL AND lease_until<%d),0) expired_leases,COALESCE(SUM(expires_at<=%d AND purged_at IS NULL),0) cleanup_pending FROM ".$s->table('exports'),$now,$now,$now,$now-900,$now-900,$now,$now));
            $stats['active_keys']=(int)$s->row($s->prepare('SELECT COUNT(*) n FROM '.$s->table('keys').' WHERE revoked_at IS NULL AND (expires_at IS NULL OR expires_at>%d)',$now))['n'];foreach($stats as$k=>$v)$stats[$k]=(int)$v;
            $add('storage',$stats['logical_bytes']>=$c['aggregate_bytes']*.8?'WARNING':'OK',eipsi_admin_format('Derived logical payload (bytes): %1$d / %2$d. This is not physical MariaDB size.',$stats['logical_bytes'],$c['aggregate_bytes']));
            $add('worker',$stats['stale_preparing']||$stats['expired_leases']?'WARNING':'OK',eipsi_admin_format('PREPARING without progress >15 min: %1$d; expired leases: %2$d. Polling and maintenance can recover.',$stats['stale_preparing'],$stats['expired_leases']));
            $age=$now-(int)($state['last_tick']??0);$add('maintenance',$stats['preparing']&&$age>900?'WARNING':'OK',$stats['preparing']&&$age>900?eipsi_admin_translate('Preparation pending without a recent tick.'):eipsi_admin_translate('No unattended preparation.'));
            $add('cleanup',$stats['cleanup_pending']&&$now-(int)($state['last_cleanup']??0)>900?'WARNING':'OK',eipsi_admin_format('Exports awaiting cleanup: %d.',$stats['cleanup_pending']));
            $schemaOk=true;foreach(array_merge(array_keys(Schema::definitions()),array_keys(ExportSchema::definitions()),array_keys(OperationsSchema::definitions()))as$slug){$r=\EIPSI_Schema_Inspector::inspect($slug);if(!$r['exists']||$r['issues'])$schemaOk=false;}
            $schemaOk=$schemaOk&&(int)get_option(\EIPSI_Schema_Migration_Runner::VERSION_OPTION,0)===\EIPSI_Schema_Migration_Runner::LATEST_VERSION;$add('schema',$schemaOk?'OK':'ERROR',$schemaOk?eipsi_admin_translate('InnoDB tables, columns and indexes verified by M8.'):eipsi_admin_translate('Critical structures or indexes are missing; review M8 migrations.'));
            $add('transactions',(int)($s->row('SELECT @@session.in_transaction active')['active']??1)===0?'OK':'WARNING',eipsi_admin_translate('Transactions available; diagnostics do not open or modify scientific data.'));
            $sample=$s->rows('SELECT id,state,manifest_json,next_source,source_count FROM '.$s->table('exports').' ORDER BY created_at DESC,id DESC LIMIT 100');$bad=0;foreach($sample as$r)if((int)$r['next_source']>(int)$r['source_count']||($r['state']==='READY'&&$r['manifest_json']===null))$bad++;
            $orphans=$s->rows('SELECT c.export_id FROM (SELECT export_id FROM '.$s->table('export_chunks').' ORDER BY export_id,kind,sequence LIMIT 100) c LEFT JOIN '.$s->table('exports').' e ON e.id=c.export_id WHERE e.id IS NULL LIMIT 1');$add('integrity',$bad||$orphans?'ERROR':'OK',eipsi_admin_format('Sample of up to 100 exports; inconsistencies: %1$d; orphan chunks detected: %2$d. No automatic scientific repair.',$bad,(int)(bool)$orphans));
        }catch(\Throwable $e){$add('database','ERROR',eipsi_admin_translate('API infrastructure unavailable; review migrations and the local connection.'));$add('schema','ERROR',eipsi_admin_translate('Could not verify the schema.'));$enabled=false;}
        $next=wp_next_scheduled('eipsi_process_nudge_jobs');
        $scheduler=\EIPSI\Scheduler\Diagnostics::inspect($now);
        $add('cron',$scheduler['health']['state'],\EIPSI\Scheduler\Admin::healthMessage($scheduler));
        $local=in_array(wp_get_environment_type(),array('local','development'),true);$scheme=parse_url(home_url(),PHP_URL_SCHEME)==='https'&&parse_url(site_url(),PHP_URL_SCHEME)==='https';$https=Authenticator::secureTransport();
        $add('tls',$enabled&&!$local&&(!$scheme||!$https)?'ERROR':(!$local&&!$scheme?'WARNING':'OK'),$local?eipsi_admin_translate('HTTP allowed only in an explicitly local/development environment.'):($scheme&&$https?eipsi_admin_translate('HTTPS configured and detected.'):eipsi_admin_translate('The API rejects insecure transport; configure trusted HTTPS in WordPress/proxy.')));
        $add('proxy',isset($_SERVER['HTTP_X_FORWARDED_PROTO'])&&(!is_ssl()||(int)($_SERVER['SERVER_PORT']??0)!==443)?'WARNING':'OK',eipsi_admin_translate('Arbitrary X-Forwarded-* headers are not trusted. The proxy must preserve Authorization and resolve duplicate headers.'));
        $free=@disk_free_space(sys_get_temp_dir());$temp=is_writable(sys_get_temp_dir());$add('temporary_storage',!$temp?'ERROR':($free!==false&&$free<$c['export_bytes']+67108864?'WARNING':'OK'),eipsi_admin_translate('Downloads use private temporary storage and prior verification; its path is not exposed.'));
        $memory=self::bytes((string)ini_get('memory_limit'));$seconds=(int)ini_get('max_execution_time');$add('php',$memory<67108864||($seconds>0&&$seconds<$c['worker_seconds']+2)?'WARNING':'OK',eipsi_admin_format('memory_limit: %1$s; max_execution_time: %2$d. The proxy may impose another timeout. Output buffering: %3$d. Upload/post limits do not limit downloads.',ini_get('memory_limit'),$seconds,(int)ini_get('output_buffering')));
        try{global$wpdb;$s=new Store();$engine=$s->row($s->prepare('SELECT ENGINE FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=%s',$wpdb->options));$unique=$s->row($s->prepare("SELECT INDEX_NAME FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=%s AND COLUMN_NAME='option_name' AND NON_UNIQUE=0 LIMIT 1",$wpdb->options));$ok=$engine&&strcasecmp($engine['ENGINE'],'InnoDB')===0&&$unique;$add('rate_limiter',$ok?'OK':'ERROR',eipsi_admin_translate('SEC-1 buckets require InnoDB options and a unique option_name index; bucket contents are not exposed.'));}catch(\Throwable $e){$add('rate_limiter','ERROR',eipsi_admin_translate('Could not verify limiter storage.'));}$add('cors','OK',eipsi_admin_translate('CORS closed: machine-to-machine integration.'));
        $add('clock','OK',eipsi_admin_translate('Local UTC; NTP is not queried and clock drift is not measured without a trusted source.'));
        $overall='OK';foreach($checks as$check){if($check['state']==='ERROR'){$overall='ERROR';break;}if($check['state']==='WARNING')$overall='WARNING';}
        return array('overall'=>$overall,'checked_at'=>gmdate('Y-m-d\TH:i:s\Z',$now),'scope'=>'CURRENT_BLOG_PREFIX','checks'=>$checks,'statistics'=>$stats,'maintenance'=>$state,'next_maintenance'=>$next?:null,'settings'=>$c);
    }
}
